SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 79 AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2019 AND 2020 AND icustays.first_careunit = 'GI' AND admissions.admission_type = 'primary' AND icustays.los IS NOT NULL;